let session=null,profile={headline:'with great power comes great responsibility',theme:'pink',display_name:''},customQuests=[],overrides={},loadingUser=null;

function suggestedQuadrant(q,date){
  const next=tests.find(t=>t.date>=date),days=next?diff(date,next.date):99;
  if(q.type==='Boss 準備'||q.type==='Boss 戰'||(days<=1&&q.subject===next?.subject))return'urgent_important';
  if(q.type==='停機')return'not_urgent_not_important';
  if(q.type==='復活'||q.type==='週結算')return'urgent_not_important';
  return'important_not_urgent';
}
function prepFor(date){const out=[];for(const t of tests){const n=diff(date,t.date);if(n===1)out.push({rank:5,type:'Boss 準備',subject:t.subject,name:`${t.scope} 完整複習`,detail:'閉書列架構 → 限時做題 → 訂正',clear:'完成 1 張重點紙、至少 5 題，寫出錯因',bonus:20});if(n===0)out.push({rank:4,type:'Boss 戰',subject:t.subject,name:`${t.scope} 考前確認`,detail:'考前只看重點，考後記不確定題目',clear:'列出 3 個考點或失分原因',bonus:25});if(n===3)out.push({rank:3,type:'主線',subject:t.subject,name:`${t.scope} 主動回憶`,detail:'不看資料先說重點，再做題驗證',clear:'說出 5 個重點並完成 5 題訂正',bonus:10});if(n===7)out.push({rank:1,type:'偵察',subject:t.subject,name:`${t.scope} 拆範圍`,detail:'分成三小塊並找最不熟處',clear:'寫 3 個小範圍與 3 個疑問',bonus:5})}return out.sort((a,b)=>b.rank-a.rank)}
function baseMissions(date){const day=date.getDay(),preps=prepFor(date),fills=filler[day].map(([type,subject,name,clear])=>({rank:type==='主線'?3:1,type,subject,name,detail:'',clear,bonus:type==='主線'?10:0}));let all=(day===2||day===4)?[...fills.slice(0,2),...preps,...fills.slice(2)]:[...preps,...fills].sort((a,b)=>b.rank-a.rank);return slots[day].map(([time,min],i)=>{const q=all[i]||{type:'停機',subject:'休息',name:'保留空白，不追加任務',detail:'',clear:'準時停止並準備睡覺',bonus:0};return{...q,id:`${iso(date)}-${i}`,date:iso(date),time,xp:q.type==='停機'?10:min+(q.bonus||0),custom:false}})}
function normalizeCustom(row){return{id:row.id,date:row.task_date,subject:row.subject,name:row.title,time:row.start_time,clear:row.clear_condition,xp:row.xp,quadrant:row.quadrant,completed:row.completed,detail:'玩家自訂關卡',type:'自訂',custom:true}}
function missionsFor(date,{includeDeleted=false}={}){const built=baseMissions(date).map(q=>{const o=overrides[q.id]||{};return{...q,completed:!!o.completed,deleted:!!o.deleted,quadrant:o.quadrant||suggestedQuadrant(q,date)}});const custom=customQuests.filter(q=>q.date===iso(date));return[...built,...custom].filter(q=>includeDeleted||!q.deleted)}
function allMissions(){return allDates.flatMap(d=>missionsFor(d))}
function totals(){const all=allMissions(),done=all.filter(q=>q.completed),xp=done.reduce((s,q)=>s+q.xp,0);return{all,done,xp,level:1+Math.floor(xp/500)}}
function streak(){const today=new Date();today.setHours(0,0,0,0);let s=0;for(let d=new Date(today>end?end:today);d>=start;d=add(d,-1)){const qs=missionsFor(d);if(qs.length&&qs.every(q=>q.completed))s++;else break}return s}
function nextBoss(){return tests.find(t=>t.date>=selected)||tests.at(-1)}
function setSyncing(on){const el=document.getElementById('cloudState');el.classList.toggle('syncing',on);el.textContent=on?'同步中':'已同步'}
function showToast(text,isError=false){const el=document.getElementById('toast');el.textContent=text;el.style.borderColor=isError?'#ff6b6b':'';el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function burst(){const box=document.getElementById('celebrate');for(let i=0;i<16;i++){const s=document.createElement('span');s.className='spark';s.textContent=i%3?'✦':'♥';s.style.left=`${20+Math.random()*60}%`;s.style.color=i%2?'var(--hot)':'var(--gold)';s.style.setProperty('--dx',`${(Math.random()-.5)*420}px`);box.appendChild(s);setTimeout(()=>s.remove(),1200)}}
function taskCard(q){const qname=quadrants.find(x=>x[0]===q.quadrant)?.[1]||'';return`<article class="quest ${q.completed?'done':''}" data-task="${esc(q.id)}"><button class="delete-quest" type="button" data-delete="${esc(q.id)}" aria-label="刪除 ${esc(q.name)}">−</button><input class="check" type="checkbox" ${q.completed?'checked':''} aria-label="完成 ${esc(q.name)}" data-check="${esc(q.id)}"><div><div class="quest-meta"><span class="pill">${esc(q.type)}</span><span class="time">${esc(q.time)}・${esc(q.subject)}</span></div><div class="quest-name">${esc(q.name)}</div>${q.detail?`<div class="quest-detail">${esc(q.detail)}</div>`:''}<div class="quadrant-badge">${esc(qname)}</div></div><div class="xp">+${q.xp} XP</div><div class="clear-condition"><b>通關：</b>${esc(q.clear)}</div></article>`}
function render(){if(!session)return;const qs=missionsFor(selected),done=qs.filter(q=>q.completed).length,t=totals(),boss=nextBoss(),remain=diff(selected,boss.date);document.body.dataset.theme=profile.theme||'pink';document.querySelector('meta[name="theme-color"]').content=getComputedStyle(document.body).getPropertyValue('--pink').trim()||'#d91672';document.getElementById('heroHeadline').textContent=profile.headline;document.title=profile.headline;document.getElementById('dateLabel').textContent=selected.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric',weekday:'short'});document.getElementById('questTitle').textContent=`${selected.getMonth()+1}/${selected.getDate()} 今日關卡`;document.getElementById('xpValue').textContent=t.xp;document.getElementById('levelValue').textContent=t.level;document.getElementById('xpNeeded').textContent=500-(t.xp%500);document.getElementById('xpFill').style.width=`${(t.xp%500)/5}%`;document.getElementById('streakValue').textContent=streak();document.getElementById('completionValue').textContent=`${done}/${qs.length}`;document.getElementById('todayXp').textContent=`今日 ${qs.filter(q=>q.completed).reduce((s,q)=>s+q.xp,0)} XP`;document.getElementById('dailyProgress').textContent=`${qs.length?Math.round(done/qs.length*100):0}%`;document.getElementById('titleValue').textContent=t.level>=10?'段考征服者':t.level>=7?'穩定輸出者':t.level>=4?'週考獵人':'新手冒險者';document.getElementById('bossTitle').textContent=`${boss.subject}｜${boss.date.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}`;document.getElementById('bossScope').textContent=boss.scope;document.getElementById('bossCountdown').textContent=remain===0?'今天開戰':remain>0?`D-${remain}`:'已完成';document.getElementById('questMatrix').innerHTML=quadrants.map(([key,title,tip])=>{const list=qs.filter(q=>q.quadrant===key);return`<section class="quadrant"><div class="quadrant-head"><div><div class="quadrant-title">${title}</div><div class="small">${tip}</div></div><span class="quadrant-count">${list.length} 關</span></div><div class="quadrant-list">${list.length?list.map(taskCard).join(''):'<div class="quadrant-empty">這一區已清空 ✦</div>'}</div></section>`}).join('');document.querySelectorAll('[data-check]').forEach(el=>el.addEventListener('change',()=>toggleTask(el.dataset.check,el.checked)));document.querySelectorAll('[data-delete]').forEach(el=>el.addEventListener('click',()=>deleteTask(el.dataset.delete)));renderStats();renderSchedule()}
function findTask(id){return missionsFor(selected,{includeDeleted:true}).find(q=>q.id===id)||allMissions().find(q=>q.id===id)}
async function toggleTask(id,value){const q=findTask(id);if(!q)return;const oldLevel=totals().level;q.completed=value;render();setSyncing(true);let error;if(q.custom){({error}=await db.from('custom_tasks').update({completed:value,updated_at:new Date().toISOString()}).eq('id',q.id).eq('user_id',session.user.id))}else{const current=overrides[q.id]||{};overrides[q.id]={...current,completed:value};({error}=await db.from('task_overrides').upsert({user_id:session.user.id,task_key:q.id,completed:value,deleted:!!current.deleted,quadrant:current.quadrant||null,updated_at:new Date().toISOString()}))}setSyncing(false);if(error){q.completed=!value;showToast('同步失敗，請再試一次',true);render();return}const newLevel=totals().level;if(value){burst();showToast(newLevel>oldLevel?`升級！你現在是 Level ${newLevel}`:'任務完成，XP 已存檔')}}
async function deleteTask(id){const q=findTask(id);if(!q)return;setSyncing(true);let error;if(q.custom){({error}=await db.from('custom_tasks').delete().eq('id',q.id).eq('user_id',session.user.id));if(!error)customQuests=customQuests.filter(x=>x.id!==q.id)}else{const current=overrides[q.id]||{};({error}=await db.from('task_overrides').upsert({user_id:session.user.id,task_key:q.id,completed:!!current.completed,deleted:true,quadrant:current.quadrant||q.quadrant,updated_at:new Date().toISOString()}));if(!error)overrides[q.id]={...current,deleted:true,quadrant:current.quadrant||q.quadrant}}setSyncing(false);if(error){showToast('刪除失敗，請再試一次',true);return}render();showToast('關卡已刪除')}
function renderSchedule(){document.getElementById('scheduleList').innerHTML=Array.from({length:7},(_,i)=>add(selected,i)).filter(d=>d<=end).map(d=>{const qs=missionsFor(d),dn=qs.filter(q=>q.completed).length;return`<article class="schedule-day ${iso(d)===iso(selected)?'today':''}"><b>${d.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric',weekday:'short'})}</b><div>${qs.slice(0,2).map(q=>esc(q.subject)+'・'+esc(q.name)).join('<br>')||'自由安排'}</div><div class="day-count">${dn}/${qs.length}</div></article>`}).join('')}
function renderStats(){const t=totals(),rate=t.all.length?Math.round(t.done.length/t.all.length*100):0;document.getElementById('totalXpStat').textContent=`${t.xp} XP`;document.getElementById('doneStat').textContent=`${t.done.length} 關`;document.getElementById('rateStat').textContent=`${rate}%`;const achievements=[['第一步',1],['十連擊',10],['百關英雄',100],['Level 5',2000]];document.getElementById('achievements').innerHTML=achievements.map(([name,need],i)=>{const unlocked=i<3?t.done.length>=need:t.xp>=need;return`<div class="achievement ${unlocked?'':'locked'}"><div class="badge">${unlocked?'✓':'?'}</div><div><b>${name}</b><div class="small">${i<3?`完成 ${need} 關`:`累積 ${need} XP`}</div></div></div>`}).join('')}
async function loadUserData(){setSyncing(true);const uid=session.user.id;const [p,c,o]=await Promise.all([db.from('profiles').select('*').eq('user_id',uid).maybeSingle(),db.from('custom_tasks').select('*').eq('user_id',uid).order('created_at'),db.from('task_overrides').select('*').eq('user_id',uid)]);const firstError=p.error||c.error||o.error;if(firstError)throw firstError;if(!p.data){const display=session.user.user_metadata?.full_name||session.user.user_metadata?.name||session.user.email?.split('@')[0]||'玩家';const created=await db.from('profiles').insert({user_id:uid,display_name:display,headline:profile.headline,theme:'pink'}).select().single();if(created.error)throw created.error;profile=created.data}else profile=p.data;customQuests=(c.data||[]).map(normalizeCustom);overrides=Object.fromEntries((o.data||[]).map(x=>[x.task_key,x]));setSyncing(false)}
function updateAccountUi(){const user=session.user,display=profile.display_name||user.user_metadata?.full_name||user.email?.split('@')[0]||'玩家',avatar=user.user_metadata?.avatar_url;document.getElementById('accountName').textContent=display;document.getElementById('accountAvatar').innerHTML=avatar?`<img class="avatar" alt="" src="${esc(avatar)}">`:`<span class="avatar">${esc(display[0]||'P')}</span>`;document.getElementById('settingsAvatar').innerHTML=avatar?`<img class="avatar" alt="" src="${esc(avatar)}">`:`<span class="avatar">${esc(display[0]||'P')}</span>`;document.getElementById('settingsName').textContent=display;document.getElementById('settingsEmail').textContent=user.email||''}
async function handleSession(next){if(loadingUser===next?.user?.id)return;session=next||null;if(!session){loadingUser=null;document.getElementById('authScreen').classList.remove('hidden');document.getElementById('loadingMask').classList.add('hidden');return}loadingUser=session.user.id;document.getElementById('authScreen').classList.add('hidden');document.getElementById('loadingMask').classList.remove('hidden');try{await loadUserData();updateAccountUi();render();document.getElementById('loadingMask').classList.add('hidden')}catch(error){console.error(error);document.getElementById('loadingMask').classList.add('hidden');showToast('資料載入失敗，請重新整理',true)}finally{loadingUser=null}}
async function signIn(){document.getElementById('authError').textContent='';const {error}=await db.auth.signInWithOAuth({provider:'google',options:{redirectTo:SITE_URL,queryParams:{prompt:'select_account'}}});if(error)document.getElementById('authError').textContent='登入沒有成功，請再試一次'}
async function signOut(){await db.auth.signOut();profile={headline:'with great power comes great responsibility',theme:'pink',display_name:''};customQuests=[];overrides={};session=null;document.getElementById('settingsDialog').close();document.getElementById('authScreen').classList.remove('hidden')}
async function switchAccount(){await db.auth.signOut();await signIn()}
function wireUi(){document.getElementById('googleSignIn').onclick=signIn;document.getElementById('accountButton').onclick=()=>{document.getElementById('headlineInput').value=profile.headline;document.querySelector(`input[name="theme"][value="${profile.theme}"]`).checked=true;document.getElementById('settingsDialog').showModal()};document.getElementById('closeSettings').onclick=()=>document.getElementById('settingsDialog').close();document.getElementById('signOutButton').onclick=signOut;document.getElementById('switchAccountButton').onclick=switchAccount;document.getElementById('prevDay').onclick=()=>{if(selected>start){selected=add(selected,-1);render()}};document.getElementById('nextDay').onclick=()=>{if(selected<end){selected=add(selected,1);render()}};document.querySelectorAll('.nav-btn').forEach(btn=>btn.onclick=()=>{renderStats();renderSchedule();document.querySelectorAll('.nav-btn,.panel').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.getElementById(btn.dataset.panel).classList.add('active')});const questDialog=document.getElementById('questDialog'),questForm=document.getElementById('customQuestForm');document.getElementById('openQuestDialog').onclick=()=>{questForm.reset();document.getElementById('customQuestDate').textContent=`${selected.toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'})}的新任務`;questDialog.showModal()};document.getElementById('cancelQuestDialog').onclick=()=>questDialog.close();questForm.addEventListener('submit',createQuest);document.getElementById('settingsForm').addEventListener('submit',saveSettings)}
async function createQuest(event){event.preventDefault();const data=new FormData(event.currentTarget),allowedXp=[20,30,40,50],xp=Number(data.get('xp')),row={user_id:session.user.id,task_date:iso(selected),subject:String(data.get('subject')).trim(),title:String(data.get('name')).trim(),start_time:String(data.get('time')),clear_condition:String(data.get('clear')).trim(),xp:allowedXp.includes(xp)?xp:30,quadrant:String(data.get('quadrant')),completed:false};setSyncing(true);const {data:created,error}=await db.from('custom_tasks').insert(row).select().single();setSyncing(false);if(error){showToast('新增失敗，請再試一次',true);return}customQuests.push(normalizeCustom(created));document.getElementById('questDialog').close();render();showToast('新關卡已加入！')}
async function saveSettings(event){event.preventDefault();const data=new FormData(event.currentTarget),next={headline:String(data.get('headline')).trim().slice(0,80)||'with great power comes great responsibility',theme:String(data.get('theme'))};setSyncing(true);const {error}=await db.from('profiles').update({...next,updated_at:new Date().toISOString()}).eq('user_id',session.user.id);setSyncing(false);if(error){showToast('設定儲存失敗',true);return}profile={...profile,...next};document.getElementById('settingsDialog').close();render();showToast('個人風格已儲存')}
function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;c.registerTool({name:'get_today_study_missions',title:'讀取今日任務',description:'取得目前選取日期的讀書任務與完成狀態。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({date:iso(selected),missions:missionsFor(selected).map(q=>({id:q.id,subject:q.subject,title:q.name,status:q.completed?'completed':'pending',quadrant:q.quadrant,xp:q.xp}))})})}
async function bootstrap(){wireUi();registerWebMCP();const {data:{session:initial}}=await db.auth.getSession();await handleSession(initial);db.auth.onAuthStateChange((_event,next)=>setTimeout(()=>handleSession(next),0))}
bootstrap();
